   private void handleDownStreamQuery(QueryStatDetailInfoArg arg) {
     if(GrayManager.isAllowByEi(RequestContextManager.getEi(),"downStreamDeptDrill") && RequestContextManager.getContext().getIsPrm()){
       List<StatFieldInfoDto> originalDimensionFields = arg.getOriginalDimensionFields();
       List<DrillCell> drillDimValues = arg.getDrillDimValues();
       boolean isDeptOrEmp=false;
       if(CollectionUtils.isNotEmpty(originalDimensionFields)){
         log.info("downStreamDeptDrill originalDimensionFields:{}", JSONObject.toJSONString(originalDimensionFields));
         isDeptOrEmp = originalDimensionFields.stream().anyMatch(t -> isDeptOrEmp(t.getFieldType(),t.getSubFieldType(),t.getType(),t.getQuoteType(),t.getDbFieldName()));
       }
       if(!isDeptOrEmp && CollectionUtils.isNotEmpty(drillDimValues)){
         log.info("downStreamDeptDrill drillDimValues:{}", JSONObject.toJSONString(drillDimValues));
         isDeptOrEmp = drillDimValues.stream().anyMatch(t->isDeptOrEmp(t.getFieldType(),t.getSubFieldType(),t.getType(),t.getQuoteType(),t.getDbFieldName()));
       }
       if(isDeptOrEmp){
         String i18nLabel = I18NMsgEnum.I18NMessageEnum.NOT_SUPPORT_SCENARID.getI18nLabel(RequestContextManagerBase.getEi(), getLangTag());
         throw new BIBizException(-1,i18nLabel);
