   private boolean checkSpecialFilters(List<FilterList> filterLists, List<String> forbiddenObj) {
     //用于保存销售记录的数据范围
     if (filterLists == null) {
       return false;
     }

     for (FilterList filterList : filterLists) {
       if (Objects.isNull(filterList)) {
         continue;
       }
       for (Filter filter : filterList.getFilters()) {
         if (filter.getIsPre() == 0 && forbiddenObj.contains(filter.getDbObjName())) {
           return true;
         }
       }
     }
     return false;
   }

